#include <algorithm>
#include <cstdio>
#include <queue>
#define Maxn 5500
#define Maxm 35500
#define INF 1000000000
using namespace std;
struct Path
{int nxt,t,c,l;}graph[Maxm];
int first[Maxn],edgeIdx=1;
void connect(int f,int t,int c,int cost){
  graph[++edgeIdx]=(Path){first[f],t,c,cost};first[f]=edgeIdx;
  graph[++edgeIdx]=(Path){first[t],f,0,-cost};first[t]=edgeIdx;
}
int S,T,preNode[Maxn],linkIdx[Maxn],flowAmount[Maxn],distance[Maxn];
bool inQueue[Maxn];
queue<int> q;
int spfa()
{
  for (int i=1;i<=T;i++)
    {distance[i]=INF;flowAmount[i]=0;}
  flowAmount[S]=INF;distance[S]=0;
  q.push(S);inQueue[S]=true;
  while(!q.empty()){
    int u=q.front();
    inQueue[u]=false;q.pop();
    for (int i=first[u],v;i;i=graph[i].nxt)
      if (graph[i].c&&distance[v=graph[i].t]>distance[u]+graph[i].l){
        distance[v]=distance[u]+graph[i].l;
        flowAmount[v]=min(flowAmount[u],graph[i].c);
        linkIdx[v]=i;preNode[v]=u;
        if (!inQueue[v]){inQueue[v]=true;q.push(v);}
     }
  }return flowAmount[T];
}
int n,m,k,C,D,pl[105][105],st[105][105];
struct Data
{int f,t;}s[105];
#define P(x,y) ((x)*n+(y))
int main()
{
  scanf("%d%d%d%d%d",&n,&m,&k,&C,&D);
  S=P(n+k,n)+1;T=S+2;
  connect(P(0,1),T,INF,0);
  for (int i=1,p;i<=k;i++){
    scanf("%d",&p);
    connect(S,P(0,p),1,0);
  }for (int i=1;i<=m;i++){
    scanf("%d%d",&s[i*2].f,&s[i*2].t);
    s[i*2-1]=(Data){s[i*2].t,s[i*2].f};
  }m*=2;
  for (int t=1;t<=n+k;t++){
    for (int i=1;i<=n;i++)
      connect(P(t-1,i),P(t,i),INF,0);
    for (int i=1;i<=m;i++){
      connect(P(t-1,s[i].f),P(t,s[i].t),1,D);
      pl[t][i]=tl;st[t][i]=1;
    }connect(P(t,1),T,INF,t*C);
  }
  int totalFlow=0,totalCost=0;
  while(int flow_now=spfa()){
    int u=T;
    while(u!=S){
      int last=preNode[u];
      graph[linkIdx[u]].c-=flow_now;
      graph[linkIdx[u]^1].c+=flow_now;
      u=last;
    }
    totalCost+=distance[T]*flow_now;
    for (int t=1;t<=n+n;t++)
      for (int i=1;i<=m;i++)
        if (graph[pl[t][i]].c){
          st[t][i]++;
          connect(P(t-1,s[i].f),P(t,s[i].t),1,D*(st[t][i]*2-1));
          pl[t][i]=tl;
        }
  }printf("%d\n",totalCost);
  return 0;
}
